16	// ── Abattoir Ghoul ────────────────────────────────────────────────
17	
18	/// Abattoir Ghoul gains life when a creature it damaged this turn dies.
19	#[test]
20	fn abattoir_ghoul_gains_life_from_damaged_creature_death() {
21	    let reg = registry();
22	    let mut state = game_at_step(Step::PrecombatMain, P0);
23	
24	    let ghoul = named_creature(&mut state, &reg, "Abattoir Ghoul", P0);
25	    let victim = ready_creature(&mut state, P1, 2, 3); // 2/3 creature
26	
27	    // Simulate the ghoul having dealt damage to the victim this turn.
28	    state.get_object_mut(victim).unwrap().damaged_by.push(ghoul);
29	    // Mark lethal damage on the victim (3 toughness, 3 damage).
30	    state.get_object_mut(victim).unwrap().damage_marked = 3;
31	
32	    // SBA should kill the victim.
33	    check_state_based_actions_with_registry(&mut state, Some(&reg));
34	    // Process death triggers.
35	    triggers::process_triggers(&mut state, &reg);
36	
37	    // Ghoul's controller (P0) should have gained 3 life (victim's toughness).
38	    assert_eq!(state.get_player(P0).life, 23, "should gain life equal to victim's toughness");
39	}
