359	    let mut state = game_at_step(Step::CombatDamage, P0);
360	
361	    // Create a creature and attach Curiosity to it.
362	    let creature = ready_creature(&mut state, P0, 2, 2);
363	    let curiosity_card_id = reg.get_id_by_name("Curiosity").unwrap();
364	    let curiosity = state.create_object(curiosity_card_id, P0, Zone::Battlefield, None, None);
365	    state.get_object_mut(curiosity).unwrap().name = "Curiosity".into();
366	    state.get_object_mut(curiosity).unwrap().attached_to = Some(creature);
367	
368	    // Give P0 a card in library to draw.
369	    let lib_card = state.create_object(mtg_engine::ids::CardId(9999), P0, Zone::Library, None, None);
370	    state.get_player_mut(P0).library_order.push(lib_card);
371	
372	    let hand_before = state.objects.values()
373	        .filter(|o| o.zone == Zone::Hand && o.owner == P0)
374	        .count();
375	
376	    // Enchanted creature deals combat damage to opponent.
377	    state.events.push(mtg_engine::events::GameEvent::CombatDamageDealt {
378	        source: creature,
379	        target: mtg_engine::events::DamageTarget::Player(P1),
380	        amount: 2,
381	    });
382	
383	    triggers::process_triggers(&mut state, &reg);
384	
385	    // Should be awaiting a yes/no choice for "you may draw a card".
386	    assert!(state.awaiting_action.is_some(), "Should be awaiting yes/no choice");
387	
388	    // Player chooses yes.
389	    state = mtg_engine::engine::submit_action(
390	        &state,
391	        &mtg_engine::actions::Action::ResolveChoice {
392	            choice: mtg_engine::actions::ResolvedChoice::PayDecision(true),
393	        },
394	        &reg,
395	    );
396	
397	    let hand_after = state.objects.values()
398	        .filter(|o| o.zone == Zone::Hand && o.owner == P0)
399	        .count();
400	    assert_eq!(hand_after, hand_before + 1, "Should have drawn 1 card from Curiosity");
401	}
