1	use crate::cards::{CardBehavior, CardData, CardRegistry, TriggerKind, TriggeredAbilityDef};
2	use crate::ids::{ObjectId, PlayerId};
3	use crate::state::GameState;
4	use crate::types::*;
5	
6	/// Falkenrath Noble — {3}{B} 2/2 Vampire Noble. Flying.
7	/// Whenever this creature or another creature dies, target player loses 1 life
8	/// and you gain 1 life.
9	pub struct FalkenrathNoble;
10	
11	impl CardBehavior for FalkenrathNoble {
12	    fn card_data(&self) -> CardData {
13	        CardData {
14	            name: "Falkenrath Noble".into(),
15	            cost: Some(ManaCost::new(vec![
16	                ManaSymbol::Generic(3),
17	                ManaSymbol::Colored(Color::Black),
18	            ])),
19	            card_types: vec![CardType::Creature],
20	            supertypes: vec![],
21	            subtypes: vec!["Vampire".into(), "Noble".into()],
22	            power: Some(2),
23	            toughness: Some(2),
24	            oracle_text: "Flying\nWhenever this creature or another creature dies, target player loses 1 life and you gain 1 life.".into(),
25	            keywords: vec![Keyword::Flying],
26	            flashback_cost: None, continuous_effects: vec![], additional_cost: None,
27	            triggered_abilities: vec![
28	                TriggeredAbilityDef {
29	                    kind: TriggerKind::SelfDies,
30	                    description: "target player loses 1 life, you gain 1 life".into(),
31	                },
32	                TriggeredAbilityDef {
33	                    kind: TriggerKind::AnyCreatureDies,
34	                    description: "target player loses 1 life, you gain 1 life".into(),
35	                },
36	            ],
37	        }
38	    }
39	
40	    fn on_dies(&self, state: &mut GameState, object_id: ObjectId, _registry: &CardRegistry) {
41	        // "This creature dies" — trigger fires even when Noble itself dies.
42	        // Use controller (last known information from when it was on the battlefield).
43	        let controller = state.get_object(object_id).map(|o| o.controller).unwrap_or(PlayerId(0));
44	        drain(state, controller);
45	    }
46	
47	    fn on_any_creature_dies(&self, state: &mut GameState, self_id: ObjectId, _dead_id: ObjectId, _dead_controller: PlayerId, _dead_damaged_by: &[ObjectId], _dead_toughness: i32, _registry: &CardRegistry) {
